"use client";

import { useParams } from "next/navigation";
import { useEffect, useState } from "react";
import { Map, Marker } from "pigeon-maps";

// ✅ TypeScript Interface
interface Hotel {
  name: string;
  vicinity: string;
  lat: number;
  lng: number;
}



const HotelFinder = () => {
 const defaultCenter: [number, number] = [28.6139, 77.209];
  const { city } = useParams();
  const [hotels, setHotels] = useState<Hotel[]>([]);
  const [mapCenter, setMapCenter] = useState(defaultCenter);

  useEffect(() => {
    if (city) {
      fetchHotels(city as string);
    }
  }, [city]);

  const fetchHotels = async (searchTerm: string) => {
    // Mocking hotel data (since Pigeon Maps doesn’t provide a search feature)
    const sampleHotels: Hotel[] = [
      {
        name: "Hotel A",
        vicinity: "City Center",
        lat: 28.6139 + 0.01,
        lng: 77.209 + 0.01,
      },
      {
        name: "Hotel B",
        vicinity: "Near Park",
        lat: 28.6139 - 0.01,
        lng: 77.209 - 0.01,
      },
      {
        name: "Hotel C",
        vicinity: "Business District",
        lat: 28.6139 + 0.02,
        lng: 77.209 + 0.02,
      },
    ];

    setHotels(sampleHotels);
    setMapCenter([sampleHotels[0].lat, sampleHotels[0].lng]);
  };

  return (
    <div className="flex gap-5 p-5">
      {/* ✅ Left Side - Hotel List */}
      <div className="w-3/5">
        <div className="mt-4">
          {hotels.length > 0 ? (
            hotels.map((hotel, index) => (
              <div key={index} className="p-3 border-b">
                <h3 className="text-lg font-semibold">{hotel.name}</h3>
                <p>{hotel.vicinity}</p>
              </div>
            ))
          ) : (
            <p className="text-gray-500">No hotels found</p>
          )}
        </div>
      </div>

      {/* ✅ Right Side - Pigeon Map */}
      <div className="w-2/5">
        <Map 
          center={mapCenter} 
          zoom={14} 
          height={500} 
          width={400}
        >
          {hotels.map((hotel, index) => (
            <Marker 
              key={index} 
              width={40} 
              anchor={[hotel.lat, hotel.lng]}
            />
          ))}
        </Map>
      </div>
    </div>
  );
};

export default HotelFinder;
